    raise exception 'PRECONDITION: apply 2027-01-31-inner-flame.sql first (the Hearth''s tables)'; end if;
end $mig$;

delete from public.hr_hearth_named;
insert into public.hr_hearth_named (item_id, xp, req_lv, flame, secs) values
